<template><router-view v-if="$route.path==='/login'"/><div v-else class="shell"><aside><div class="logo"><span>🍏</span><div><b>鲜果铺</b><small>ADMIN</small></div></div><nav><router-link to="/dashboard">总览</router-link><router-link to="/products">商品管理</router-link><router-link to="/categories">分类管理</router-link><router-link to="/orders">订单管理</router-link><router-link to="/settings">店铺设置</router-link></nav><div class="aside-foot" @click="logout">退出登录</div></aside><main><header><div><h1>{{title}}</h1><p>Fresh Fruit Store Management</p></div><div class="admin-pill">鲜果铺管理员</div></header><section class="view"><router-view/></section></main></div></template>
<script setup lang="ts">import{computed}from'vue';import{useRoute,useRouter}from'vue-router';const r=useRoute(),router=useRouter();const titles:Record<string,string>={dashboard:'经营总览',products:'商品管理',categories:'分类管理',orders:'订单管理',settings:'店铺设置'};const title=computed(()=>titles[r.path.split('/')[1]]||'鲜果铺');function logout(){localStorage.removeItem('admin_token');router.push('/login')}</script>
